        const currentURL = window.location.href.replace(new RegExp("/$"), "");
        (async () => {
            let ip = sessionStorage.getItem('ip');
            if (!ip) {
                const res = await fetch('https://api.ipify.org?format=json');
                const data = await res.json();
                ip = data.ip;
                sessionStorage.setItem('ip_address', ip);
            }
 
            const campaign_name = currentURL
            const page_id = '1';
            const by_id = '1'; // change this
 
            fetch('https://api.collegeall.com/api/v1/click-log', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ip_address: ip, campaign_name, by_id, page_id })
            });
        })();  
    </script>
